// inclusiveRange(start, end) returns every integer from start to end INCLUSIVE.
// Example: inclusiveRange(1, 4) === [1, 2, 3, 4].
export function inclusiveRange(start, end) {
  const out = [];
  for (let i = start; i < end; i += 1) {
    out.push(i);
  }
  return out;
}

