import { test } from "node:test";
import assert from "node:assert/strict";
import { inclusiveRange } from "../src/range.mjs";

test("range is inclusive at both ends", () => {
  assert.deepEqual(inclusiveRange(1, 4), [1, 2, 3, 4]);
});

test("range of one element", () => {
  assert.deepEqual(inclusiveRange(7, 7), [7]);
});

test("empty when start is past end", () => {
  assert.deepEqual(inclusiveRange(5, 4), []);
});
